import {uid} from './model.js';
import {newScene,prepareScene,sceneIssues} from './authoring-model.js';
import {storyData,storyEvent,addStoryBeat,addStoryLink,applyStoryPrerequisite,syncStoryScenes,rebindStoryBeat} from './story-model.js';

export function storyWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc,state={active:false,selected:null,connecting:null,cam:{x:35,y:35,scale:.8}};
 const host=document.createElement('section');host.id='storyWorkspace';host.className='story-workspace';host.hidden=true;document.querySelector('#app').append(host);
 const data=()=>storyData(api.project());let drag=null,pinch=null,pointers=new Map(),frame=0;
 const cancelFrame=()=>{if(frame)cancelAnimationFrame(frame);frame=0;};
 function close(){state.active=false;host.hidden=true;state.connecting=null;drag=null;pinch=null;pointers.clear();cancelFrame();api.leave();}
 function open(){state.active=true;state.connecting=null;host.hidden=false;host.innerHTML=`<header class="story-header"><button id="storyExit" type="button">← Map editor</button><div><b>Story</b><small>Maps, scenes and story flow</small></div><button id="storyAdd" type="button">＋ Card</button><button id="storySync" type="button">Import scenes</button><button id="storyFit" type="button">Fit</button></header><div id="storyBoard" class="story-board" aria-label="Story graph. Drag cards to move them; drag empty space to pan."><div id="storyPlane" class="story-plane"><svg id="storyLinks" class="story-links" aria-label="Story connections"></svg><div id="storyCards"></div></div><div id="storyEmpty" class="story-empty">Add story cards, or import the scenes already in your project.</div></div><footer class="story-footer"><span id="storyStatus"></span><button id="storyZoomOut" type="button" aria-label="Zoom out">−</button><button id="storyZoomIn" type="button" aria-label="Zoom in">+</button><button id="storyConnect" type="button">Connect</button><button id="storyEdit" type="button">Edit selected</button></footer>`;
  $('#storyExit').onclick=close;$('#storyAdd').onclick=()=>editBeat();$('#storySync').onclick=()=>{try{let added;api.change(()=>added=syncStoryScenes(api.project()));render();api.toast(added+' scenes added to the story.');}catch(e){api.error(e);}};$('#storyFit').onclick=fit;$('#storyZoomOut').onclick=()=>zoom(.8);$('#storyZoomIn').onclick=()=>zoom(1.25);$('#storyConnect').onclick=()=>{if(!state.selected){api.toast('Select the first story card.');return;}state.connecting=state.selected;renderStatus();};$('#storyEdit').onclick=()=>{const beat=data().beats.find(b=>b.id===state.selected);if(beat)editBeat(beat);};attachBoard();render();fit();
 }
 function transformed(){const c=state.cam;$('#storyPlane').style.transform=`translate(${c.x}px,${c.y}px) scale(${c.scale})`;}
 function renderStatus(){const s=data();$('#storyStatus').textContent=state.connecting?'Tap another card to connect.':s.beats.length+' cards · '+s.links.length+' links';$('#storyConnect').disabled=!state.selected;$('#storyEdit').disabled=!state.selected;}
 function render(){if(!state.active)return;const s=data();if(!s.beats.some(b=>b.id===state.selected))state.selected=null;
  $('#storyCards').innerHTML=s.beats.map(b=>{const {map,event}=storyEvent(api.project(),b),issues=b.eventId&&!event?1:event?.runtime?.action==='scene'?sceneIssues(event,api.project(),map).length:0;return`<article class="story-card ${state.selected===b.id?'selected':''} ${issues?'needs-attention':''}" data-story-beat="${b.id}" style="left:${b.x}px;top:${b.y}px"><small>${esc(b.type||'note')} · ${issues?'needs attention':esc(b.status||'planned')}</small><b>${esc(b.title)}</b><p>${esc(b.summary||event?.title||'Add story notes')}</p><span>${esc(map?.name||'Not linked to a map')}${event?' · '+esc(event.title):''}</span><div><button data-story-edit="${b.id}" type="button">Edit</button>${event?`<button data-story-event="${b.id}" type="button">Actions</button>`:''}${map?`<button data-story-map="${b.id}" type="button">Map ↗</button>`:''}</div></article>`;}).join('');
  $('#storyEmpty').hidden=!!s.beats.length;$('#storyCards').querySelectorAll('[data-story-edit]').forEach(b=>b.onclick=()=>editBeat(s.beats.find(n=>n.id===b.dataset.storyEdit)));$('#storyCards').querySelectorAll('[data-story-event]').forEach(b=>b.onclick=()=>editEvent(s.beats.find(n=>n.id===b.dataset.storyEvent)));$('#storyCards').querySelectorAll('[data-story-map]').forEach(b=>b.onclick=()=>{const beat=s.beats.find(n=>n.id===b.dataset.storyMap),{map,event}=storyEvent(api.project(),beat);close();api.openMap(map.id,event);});drawLinks();transformed();renderStatus();
 }
 function drawLinks(){if(!state.active)return;const s=data(),positions=new Map(s.beats.map(b=>[b.id,drag?.beat?.id===b.id&&drag.moved?{...b,x:drag.nextX??b.x,y:drag.nextY??b.y}:b]));$('#storyLinks').innerHTML=s.links.map(l=>{const a=positions.get(l.from),b=positions.get(l.to);if(!a||!b)return'';const x1=a.x+240,y1=a.y+65,x2=b.x,y2=b.y+65,bend=Math.max(60,Math.abs(x2-x1)*.45);return`<g><path data-story-edge="${l.id}" class="${l.applyPrerequisite?'story-required':''}" d="M${x1},${y1} C${x1+bend},${y1} ${x2-bend},${y2} ${x2},${y2}"/><text x="${(x1+x2)/2}" y="${(y1+y2)/2-8}">${esc(l.label)}${l.applyPrerequisite?' · prerequisite':''}</text></g>`;}).join('');$('#storyLinks').querySelectorAll('[data-story-edge]').forEach(p=>p.onclick=e=>{e.stopPropagation();editLink(s.links.find(l=>l.id===p.dataset.storyEdge));});}
 function zoom(factor,px=null,py=null){const r=$('#storyBoard').getBoundingClientRect(),c=state.cam,x=px??r.width/2,y=py??r.height/2,next=Math.max(.2,Math.min(2,c.scale*factor));c.x=x-(x-c.x)/c.scale*next;c.y=y-(y-c.y)/c.scale*next;c.scale=next;transformed();}
 function fit(){const s=data(),r=$('#storyBoard').getBoundingClientRect();if(!s.beats.length){state.cam={x:35,y:35,scale:.8};transformed();return;}const x=Math.min(...s.beats.map(b=>b.x)),y=Math.min(...s.beats.map(b=>b.y)),w=Math.max(...s.beats.map(b=>b.x))+240-x,h=Math.max(...s.beats.map(b=>b.y))+150-y,scale=Math.max(.2,Math.min(1,(r.width-50)/w,(r.height-50)/h));state.cam={x:(r.width-w*scale)/2-x*scale,y:(r.height-h*scale)/2-y*scale,scale};transformed();}
 function attachBoard(){const board=$('#storyBoard');
  board.addEventListener('pointerdown',e=>{if(e.target.closest('button,[data-story-edge]'))return;e.preventDefault();board.setPointerCapture?.(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const[a,b]=[...pointers.values()];pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),scale:state.cam.scale};drag=null;return;}const card=e.target.closest('[data-story-beat]'),beat=card&&data().beats.find(b=>b.id===card.dataset.storyBeat);if(beat&&state.connecting){try{let link;api.change(()=>link=addStoryLink(api.project(),state.connecting,beat.id));state.connecting=null;render();editLink(link);}catch(error){api.error(error);}return;}drag={beat,element:card,startX:e.clientX,startY:e.clientY,x:beat?.x??state.cam.x,y:beat?.y??state.cam.y,moved:false};});
  board.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pinch&&pointers.size>=2){const[a,b]=[...pointers.values()];zoom(pinch.scale*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,pinch.distance)/state.cam.scale);return;}if(!drag||pinch)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;drag.moved||=Math.hypot(dx,dy)>5;if(drag.beat){drag.nextX=Math.round((drag.x+dx/state.cam.scale)/10)*10;drag.nextY=Math.round((drag.y+dy/state.cam.scale)/10)*10;drag.element.style.left=drag.nextX+'px';drag.element.style.top=drag.nextY+'px';if(!frame)frame=requestAnimationFrame(()=>{frame=0;drawLinks();});}else{state.cam.x=drag.x+dx;state.cam.y=drag.y+dy;transformed();}});
  const end=e=>{pointers.delete(e.pointerId);if(pointers.size)return;if(drag?.beat){const current=drag;if(current.moved)api.change(()=>{current.beat.x=current.nextX??current.x;current.beat.y=current.nextY??current.y;});state.selected=current.beat.id;}drag=null;pinch=null;render();};board.addEventListener('pointerup',end);board.addEventListener('pointercancel',()=>{pointers.clear();drag=null;pinch=null;render();});board.addEventListener('wheel',e=>{e.preventDefault();const r=board.getBoundingClientRect();zoom(e.deltaY>0?.9:1.1,e.clientX-r.left,e.clientY-r.top);},{passive:false});
 }
 function editBeat(old=null){const b=structuredClone(old||{id:uid(),title:'New story beat',type:'note',status:'planned',summary:'',x:Math.round((80-state.cam.x)/state.cam.scale/10)*10,y:Math.round((80-state.cam.y)/state.cam.scale/10)*10}),maps=api.project().maps,events=maps.flatMap(m=>m.markers.filter(n=>n.runtime).map(n=>({m,n})));
  api.modal(old?'Edit story card':'New story card',`<label>Title<input id="storyBeatTitle" maxlength="120" value="${esc(b.title)}"></label><div class="field-row"><label>Type<select id="storyBeatType">${['chapter','scene','choice','note'].map(t=>`<option ${t===b.type?'selected':''}>${t}</option>`).join('')}</select></label><label>Status<select id="storyBeatStatus">${['planned','draft','ready'].map(t=>`<option ${t===b.status?'selected':''}>${t}</option>`).join('')}</select></label></div><label>Story notes<textarea id="storyBeatSummary" maxlength="8000">${esc(b.summary)}</textarea></label><label>Linked map<select id="storyBeatMap"><option value="">No map</option>${maps.map(m=>`<option value="${m.id}" ${m.id===b.mapId?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label>Linked event / scene<select id="storyBeatEvent"><option value="">No event</option>${events.map(({m,n})=>`<option value="${n.id}" ${n.id===b.eventId?'selected':''}>${esc(m.name+' / '+n.title)}</option>`).join('')}</select></label>${old?'<div class="studio-actions"><button id="storyNewScene" type="button">Create a linked scene</button><button id="storyDeleteBeat" type="button" class="danger">Remove card</button></div>':''}<p class="hint-line">Story notes describe the flow. Actions edits the actual linked event. Connections can optionally enforce a saved prerequisite between visual scenes.</p>`,()=>{b.title=$('#storyBeatTitle').value.trim()||'Story beat';b.type=$('#storyBeatType').value;b.status=$('#storyBeatStatus').value;b.summary=$('#storyBeatSummary').value;b.mapId=$('#storyBeatMap').value||null;b.eventId=$('#storyBeatEvent').value||null;if(b.eventId)b.mapId=events.find(e=>e.n.id===b.eventId)?.m.id||b.mapId;api.change(()=>{if(old)rebindStoryBeat(api.project(),old,b);else addStoryBeat(api.project(),b);});state.selected=b.id;render();},'Save card');
  if(old){$('#storyNewScene').onclick=()=>createScene(old);$('#storyDeleteBeat').onclick=()=>{api.change(()=>{for(const l of data().links.filter(l=>l.from===old.id||l.to===old.id))applyStoryPrerequisite(api.project(),l,false);data().links=data().links.filter(l=>l.from!==old.id&&l.to!==old.id);data().beats=data().beats.filter(b=>b.id!==old.id);});api.close();render();};}
 }
 function editEvent(beat){const {map,event}=storyEvent(api.project(),beat);if(!event){api.toast('Link this card to an event first.');return;}api.loadMap(map.id);if(event.runtime?.action==='scene')api.scenes().edit(event);else api.events().edit(event);}
 function createScene(beat){api.modal('Create linked scene',`<label>Map<select id="storySceneMap">${api.project().maps.map(m=>`<option value="${m.id}" ${m.id===beat.mapId?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><div class="field-row"><label>Tile X<input id="storySceneX" type="number" min="0" value="1"></label><label>Tile Y<input id="storySceneY" type="number" min="0" value="1"></label></div>`,()=>{const map=api.project().maps.find(m=>m.id===$('#storySceneMap').value),x=+$('#storySceneX').value,y=+$('#storySceneY').value;if(!map||![x,y].every(Number.isInteger)||x<0||y<0||x>=map.width||y>=map.height)throw Error('Choose a tile inside the linked map.');let n;api.change(()=>{n=newScene(api.project(),x,y);n.title=beat.title;prepareScene(api.project(),n);map.markers.push(n);rebindStoryBeat(api.project(),beat,{mapId:map.id,eventId:n.id,type:'scene',status:'draft'});});render();api.loadMap(map.id);api.scenes().edit(n);return false;},'Create & edit scene');}
 function editLink(link){api.modal('Story connection',`<label>Label<input id="storyLinkLabel" maxlength="120" value="${esc(link.label)}"></label><label class="check"><input id="storyLinkPrerequisite" type="checkbox" ${link.applyPrerequisite?'checked':''}> Require the first visual scene to complete before the second can run</label><p>A normal connection is a story-planning link. The prerequisite option edits the target scene's actual saved conditions.</p><button id="storyDeleteLink" type="button" class="danger">Remove connection</button>`,()=>{api.change(()=>{applyStoryPrerequisite(api.project(),link,$('#storyLinkPrerequisite').checked);link.label=$('#storyLinkLabel').value.trim()||'Next';});render();},'Save connection');$('#storyDeleteLink').onclick=()=>{api.change(()=>{applyStoryPrerequisite(api.project(),link,false);data().links=data().links.filter(l=>l.id!==link.id);});api.close();render();};}
 return {state,open,close,render};
}
